// Calculate weighted score
let score = ($critical_flags * 50) + ($high_flags * 25) + ($medium_flags * 10);

// Cap the score at 100
if (score > 100) score = 100;

let routing_decision = "";

// The Conditional Escalation Logic
if (score >= 75) {
    routing_decision = "ACTION: ESCALATE TO HITL (Human-in-the-Loop) REVIEW QUEUE. Transaction is blocked.";
} else if (score >= 40) {
    routing_decision = "ACTION: ROUTE TO QA SAMPLING. High risk detected.";
} else if (score > 0) {
    routing_decision = "ACTION: AUTO-CLASSIFY EXCEPTION. Medium risk detected.";
} else {
    routing_decision = "ACTION: AUTO-APPROVE. No risks detected.";
}

return `CALCULATED RISK SCORE: ${score}/100. ${routing_decision}`;
